  native_speech: [
    { pt: "Ó pá, isso não faz sentido nenhum!", en: "Dude, that makes no sense at all!", es: "¡Tío, eso no tiene ningún sentido!", fr: "Mec, ça n'a aucun sens !", hi: "यार, इसमें कोई तुक नहीं!", ur: "یار، اس میں کوئی تک نہیں!", ar: "يا رجل، هذا لا معنى له!", bn: "এই দোস্ত, এতে কোনো মানেই হয় না!", de: "Alter, das ergibt überhaupt keinen Sinn!", zh: "老兄，这完全没有道理！", ru: "Чувак, это вообще бессмысленно!", uk: "Друже, це взагалі безглузді!", tr: "Dostum, bunun hiç anlamı yok!", pl: "Stary, to w ogóle nie ma sensu!", ko: "야, 그건 말도 안 돼!", ja: "おい、それは全然意味がないよ！" },
    { pt: "Pronto, está feito. Demorou, mas ficou fixe.", en: "Done. It took a while, but it turned out great.", es: "Listo, ya está. Tardó, pero quedó genial.", fr: "Voilà, c'est fait. Ça a pris du temps, mais c'est réussi.", hi: "बस, हो गया। समय लगा, लेकिन अच्छा हुआ।", ur: "بس، ہو گیا۔ وقت لگا، لیکن اچھا ہوا۔", ar: "خلاص. أخذ وقتًا، لكن طلع حلو.", bn: "হয়ে গেল। সময় লেগেছে, কিন্তু ভালো হয়েছে।", de: "So, erledigt. Hat gedauert, aber ist gut geworden.", zh: "好了，搞定了。虽然花了点时间，但效果很好。", ru: "Готово. Заняло время, но получилось круто.", uk: "Готово. Тривало довго, але вийшло класно.", tr: "Tamam, oldu. Zaman aldı ama güzel oldu.", pl: "Gotowe. Trochę trwało, ale wyszło super.", ko: "됐어, 다 했어. 시간 좀 걸렸지만 잘 됐어요.", ja: "できた。時間かかったけど、いい感じになったよ。" },
    { pt: "Epa, calma, não é preciso exagerar.", en: "Hey, relax, no need to overreact.", es: "Oye, calma, no es necesario exagerar.", fr: "Hé, calme-toi, pas besoin d'exagérer.", hi: "अरे, शांत हो, इतना बढ़ा-चढ़ाकर बोलने की ज़रूरत नहीं।", ur: "ارے، پرسکون ہو، اتنا بڑھا چڑھا کر بولنے کی ضرورت نہیں۔", ar: "يا، اهدأ، ما في داعي للمبالغة.", bn: "এই, শান্ত হও, বাড়াবাড়ির দরকার নেই।", de: "Hey, ruhig, man muss nicht übertreiben.", zh: "嘿，冷静，不用小题大做。", ru: "Эй, спокойно, не надо преувеличивать.", uk: "Ей, спокійно, не треба перебільшувати.", tr: "Hey, sakin ol, abartmaya gerek yok.", pl: "Ej, spokojnie, nie trzeba przesadzać.", ko: "야, 진정해, 과장할 필요 없어.", ja: "おい、落ち着いて、大げさにする必要ないよ。" },
    { pt: "Tipo, eu acho que isso não vai funcionar, sabes?", en: "Like, I think that's not going to work, you know?", es: "O sea, creo que eso no va a funcionar, ¿sabes?", fr: "Genre, je pense que ça va pas marcher, tu sais ?", hi: "मतलब, मुझे लगता है कि ये काम नहीं करेगा, पता है ना?", ur: "مطلب، مجھے لگتا ہے یہ کام نہیں کرے گا، سمجھے؟", ar: "يعني، أعتقد أن هذا لن ينجح، عارف؟", bn: "মানে, আমার মনে হয় এটা কাজ করবে না, বুঝলে?", de: "Also, ich glaube, das wird nicht klappen, weißt du?", zh: "就是说，我觉得这行不通，你懂吗？", ru: "Типа, я думаю, это не сработает, знаешь?", uk: "Типу, я думаю, це не спрацює, знаєш?", tr: "Yani, bunun işe yaramayacağını düşünüyorum, biliyor musun?", pl: "No, myślę, że to nie zadziała, wiesz?", ko: "그러니까, 이건 안 될 것 같거든, 알지?", ja: "なんか、うまくいかないと思うんだよね、わかる？" },
  ],

